CustomField.formula:
IF ( ( TEXT(BizRegion__c) = 'LK_KR' || TEXT(BizRegion__c) = 'LK_A&G' ) && TEXT(Currency__c) = 'KRW' , Total_Premium_Amount__c  *  1,
    IF ( TEXT(BizRegion__c) = 'LK_Re' && TEXT(Currency__c) = 'USD' , Total_Premium_Amount__c  *  1,
        IF ( TEXT(BizRegion__c) = 'LK_VN' && TEXT(Currency__c) = 'VDN' , Total_Premium_Amount__c  *  1,
           IF ( NOT(ISBLANK(ExchangeRatePolicy__c)), Total_Premium_Amount__c * ExchangeRatePolicy__c, Total_Premium_Amount__c * ExchangeRate__c )
           )
        )
    )
